package app.stak.nativeapp.data

import org.junit.Assert.*
import org.junit.Test
class TorznabTest {
    private val hash="a".repeat(40)
    private val caps="""<caps><limits max="200"/><searching><search available="no" supportedParams="q"/><movie-search available="yes" supportedParams="imdbid,tmdbid"/><tv-search available="yes" supportedParams="imdbid,tvdbid,season,ep"/></searching></caps>"""
    @Test fun aiostreamsUsesIdsInsteadOfUnsupportedTitleQueries(){val params=nabQueryParameters(parseNabCaps(caps),NabQuery("movie","tt1234567",title="Film"));assertEquals("movie",params["t"]);assertEquals("1234567",params["imdbid"]);assertFalse(params.containsKey("q"))}
    @Test fun episodeQueryKeepsSeasonAndEpisodeDistinct(){val params=nabQueryParameters(parseNabCaps(caps),NabQuery("series","tt1234567",season=2,episode=3));assertEquals("tvsearch",params["t"]);assertEquals("2",params["season"]);assertEquals("3",params["ep"])}
    @Test fun seasonPackQueryOmitsEpisode(){val params=nabQueryParameters(parseNabCaps(caps),NabQuery("series","tt1234567",season=2,episode=1,pack=true));assertEquals("2",params["season"]);assertFalse(params.containsKey("ep"))}
    @Test fun textOnlyIndexerUsesTitleAndEpisode(){val params=nabQueryParameters(NabCaps(generic=NabSearch(true,setOf("q"))),NabQuery("series","tt1234567",title="Show",season=2,episode=3));assertEquals("search",params["t"]);assertEquals("Show S02E03",params["q"])}
    @Test(expected=NabFailure::class) fun unsupportedIdOnlyIndexerDoesNotPretendToFindResults(){nabQueryParameters(NabCaps(tv=NabSearch(true,setOf("tvdbid","season","ep"))),NabQuery("series","tt1234567",season=1,episode=1))}
    @Test fun copiedApiKeyIsSeparatedAndAioBaseIsNormalized(){val item=normalizeTorznabIndexer(TorznabIndexer(name="AIO",url="https://example.test/api/v1/torznab?apikey=uuid%3Asecret&t=caps"));assertEquals("uuid:secret",item.apiKey);assertEquals("https://example.test/api/v1/torznab/api",item.url);assertFalse(item.toString().contains("secret"))}
    @Test fun genericIndexerPathsAreNotGuessed(){assertEquals("http://192.168.1.2:9117/api/v2.0/indexers/all/results/torznab/api",normalizeTorznabIndexer(TorznabIndexer(name="Jackett",url="http://192.168.1.2:9117/api/v2.0/indexers/all/results/torznab/api")).url)}
    @Test fun rssMagnetRetainsPrivateTrackersAndReportedSize(){val xml="""<rss xmlns:torznab="http://torznab.com/schemas/2015/feed"><channel><item><title>Film.2160p.REMUX.HDR</title><guid>release-1</guid><link>magnet:?xt=urn:btih:$hash&amp;tr=https%3A%2F%2Ftracker.example%2Fsecret%2Fannounce</link><enclosure url="https://indexer.test/get/1" type="application/x-bittorrent" length="50"/><torznab:attr name="size" value="1000000"/><torznab:attr name="seeders" value="8"/></item></channel></rss>""";val item=parseNabPage(xml).items.single();assertEquals(hash,item.hash);assertTrue(item.magnet!!.contains("tr="));assertEquals(1000000L,item.size);val source=nabRelease(item,TorznabIndexer(name="Indexer",url="https://indexer.test/api"));assertEquals("2160p",source.resolution);assertTrue(source.remux);assertTrue(source.hdr);assertEquals(1000000L,source.torrentSizeBytes);assertTrue(source.canImport)}
    @Test fun torrentFileOnlyResultIsImportableWithoutInventingHash(){val item=NabItem("Film.1080p.WEB-DL","id",null,null,"http://indexer.test/file.torrent",1000);val source=nabRelease(item,TorznabIndexer(name="Indexer",url="http://indexer.test/api"));assertNull(source.infoHash);assertTrue(source.canImport);assertTrue(source.sourceIdentity.startsWith("torznab:"));assertNull(source.streamUrl)}
    @Test fun playbackLinkIsNeverImportedAsTorrent(){val source=parseSourceRelease(com.google.gson.JsonParser.parseString("""{"url":"https://cdn.test/movie.mp4","title":"Film"}""").asJsonObject)!!;assertFalse(source.canImport)}
    @Test fun nzbAndVideoEnclosuresAreNotTorrentCandidates(){val xml="""<rss><channel><item><title>Film</title><enclosure url="https://indexer.test/file.nzb" type="application/x-nzb"/></item><item><title>Other</title><enclosure url="https://cdn.test/video.mp4" type="video/mp4"/></item></channel></rss>""";assertTrue(parseNabPage(xml).items.isEmpty())}
    @Test(expected=IllegalArgumentException::class) fun xmlEntitiesAreRejected(){parseNabPage("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///private'>]><rss><channel/></rss>")}
    @Test(expected=NabFailure::class) fun xmlApiErrorsAreNotSuccessfulEmptySearches(){parseNabPage("<error code='100' description='Invalid API key'/>")}
    @Test(expected=IllegalArgumentException::class) fun htmlLoginPageIsNotCapabilities(){parseNabCaps("<html><body>Login</body></html>")}

    @Test fun duplicateHashKeepsImportablePrivateTorrentMetadata(){val hashOnly=SourceRelease("Film",infoHash=hash);val file=hashOnly.copy(torznabIndexerId="private",torrentFileUrl="https://indexer.test/private.torrent");assertEquals(file,mergeSourceCandidates(listOf(hashOnly,file)).single())}
    @Test fun stremioMagnetTrackersArePreserved(){val source=parseSourceRelease(com.google.gson.JsonParser.parseString("""{"url":"magnet:?xt=urn:btih:$hash&tr=https%3A%2F%2Ftracker.test%2Fprivate","title":"Film"}""").asJsonObject)!!;assertTrue(source.magnetUrl!!.contains("tr="))}

    @Test fun v2MagnetDoesNotInvalidateOtherIndexerResults(){val magnet="magnet:?xt=urn:btmh:1220"+"b".repeat(64);val source=parseSourceRelease(com.google.gson.JsonParser.parseString("""{"url":"$magnet","title":"Film"}""").asJsonObject)!!;assertNull(source.infoHash);assertTrue(source.canImport);assertTrue(source.sourceIdentity.startsWith("urn:btmh:")||source.sourceIdentity.startsWith("btmh:"))}
}
